// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 seedAmount, uint256 value, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        seedAmount = bound(seedAmount, 0, type(uint128).max);
        // fund the contract via its fallback
        vm.deal(address(this), seedAmount);
        (bool okPay,) = address(c).call{value: seedAmount}("");
        assertTrue(okPay);

        vm.assume(value <= address(c).balance);

        uint256 before = address(c).balance;
        vm.prank(c.owner());
        c.withdraw(value);

        assertTrue(address(c).balance == before - value);
    }

    receive() external payable {}
}
